#!/bin/bash
# Owner-attended slpa runs (worklog 2026-11-05 10:02): arm one, tell the owner, reboot into it.
#   bash harness/psci-efi/attended.sh A|B|C [--dry]
# A: slpa (deep_steps 6), 30 s alarm; with the test kernel's ANS IO RVBAR restore since 11-05 17:36. B: A + PMU boot stage 0x50 (deep_steps 14). C: B + the PMP steps (pmp-sleep; IDLE sent once since 11-05 18:00).
# Image 52's Aura S2R steps (worklog 2026-11-05 evening), each with slpa: D: the PMGR's S2R timer (aura-ctl 1).
# E: D + every core into macOS's deep sleep (aura-ctl 3). F: the cores alone, no timer (aura-ctl 2), the control.
# Image 53 (worklog 2026-11-05, "image 53"): G: E + quiesceHW's power domains (aura-ctl 7). H: G + its ClkGen and
# PLL-off writes (aura-ctl 15), i.e. all of AppleT6020PMGR::quiesceHW but the cluster power-off, in macOS's order.
# I: C + H, the PMP's IDLE after slpa and the whole quiesce before the timer, as macOS does both (worklog 11-05 21:3x).
# Every run: image 53 (install.sh BIN2; aura-ctl 0 is image 51), 1 deep cycle, root read-only, the PMGR state
# counters on, dead-man switch.
# Run only when the owner has said they are at the Mac and ready to reset by hand.
set -eu
RUN=${1:?A to F}; DRY=${2:-}; ALARM=30
# REL=1 (default): the PMP's display requests released for sleep (pmp_report.test_release_aon, 11-05 18:16).
# NEXT="G H": after recording this run, the next session arms the first of these (owner still attended).
REL=${REL:-1}; NEXT=${NEXT:-}; AOP=0
# EXTRA="...": appended to the next session's prompt (e.g. what to run after this one).
EXTRA=${EXTRA:-}; WO=0; UT=0; DO=0; PC=${PC:-0}; SK=${SK:-}; RA=0; HM=${HM:-0}; KEY=0; WX=${WX:-}; PIDS=${PIDS:-}; GD=0; UB=0; KIND="OWNER-ATTENDED slpa run"
H=$(cd "$(dirname "$0")" && pwd)
L=/var/lib/deepidle
case $RUN in
    A) DS=6;  PMP=0; CTL=0 ;;
    B) DS=14; PMP=0; CTL=0 ;;
    C) DS=14; PMP=1; CTL=0 ;;
    D) DS=6;  PMP=0; CTL=1 ;;
    D2) DS=6; PMP=0; CTL=1; ALARM=90 ;;   # D with a later alarm: does the reset follow the alarm or the timer?
    E) DS=6;  PMP=0; CTL=3 ;;
    F) DS=6;  PMP=0; CTL=2 ;;
    G) DS=6;  PMP=0; CTL=7 ;;    # image 53: E + quiesceHW's domains (AFR off, SIO auto-enable off)
    H) DS=6;  PMP=0; CTL=15 ;;   # image 53: G + quiesceHW's ClkGen and PLL-off writes
    I) DS=14; PMP=1; CTL=15 ;;   # C + H: the PMP's IDLE and all of image 53's quiesceHW before the timer, as macOS
    J) DS=14; PMP=1; CTL=31; AOP=3 ;;   # I + the AOP's sleep handshake + image 54's soc-cluster power-off: all of macOS's steps found
    K) DS=14; PMP=1; CTL=15; AOP=3 ;;   # J without the cluster power-off (I + the AOP handshake), if J resets in a new way
    L) DS=30; PMP=1; CTL=31; AOP=3 ;;
    M) DS=30; PMP=1; CTL=31; AOP=3; KEY=1 ;;   # L with the owner pressing the power key once ~3 min after the push: does the key wake it, and did the SoC sleep?   # J + macOS's AP wake mask (deep_steps bit 16): D to J all ran with every wake source enabled
    W) DS=16; PMP=0; CTL=0; AOP=3; KIND="UNATTENDED normal-path (no slpa) wake-bisect run"
       [ -n "$WX" ] || { echo "W needs WX=w0,...,w8 (tools/wake-bisect.py next)"; exit 2; } ;;   # macOS's mask + WX, no slpa: does the alarm wake Aura's deep WFI?
    P) DS=0; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; KIND="UNATTENDED normal-path (no slpa) check run" ;;   # ISP_SYS's PMP request withdrawn for sleep too: does it ack, and come back?
    Q) DS=32; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; KIND="UNATTENDED normal-path (no slpa) check run" ;;   # deep_steps bit 32: the PMP's requests withdrawn in suspend_late, asserted in resume_early
    N) DS=62; PMP=1; CTL=31; AOP=3; PIDS=${PIDS:-0x1000} ;;   # L + bit 32: the PMP's request word at 0 before slpa and its IDLE, as macOS's trace
    R) DS=62; PMP=1; CTL=63; AOP=3; PIDS=${PIDS:-0x1000} ;;   # N + image 55's PMGR stop request per secondary before it sleeps (macOS's CPUSTART writes)
    G55) DS=0; PMP=0; CTL=128; AOP=3; KIND="UNATTENDED normal-path (no slpa) image 55 regression run" ;;   # aura-ctl 0x80 marker only
    S) DS=96; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; KIND="UNATTENDED normal-path (no slpa) power-domain dump run" ;;   # the PMP release + a dump of the PMGR domains not off at suspend_late (11-06 16:48: hung the suspend, WD1; do not repeat)
    S2) DS=32; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; KIND="UNATTENDED normal-path (no slpa) genpd dump run" ;;   # the PMP release + genpd's own list of domains still on at syscore suspend (no register reads)
    U) DS=32; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; UB=1; KIND="UNATTENDED normal-path (no slpa) unbind run" ;;   # S2 + the display stack and the USB-C dwc3s unbound first
    S6) DS=32; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; WO=1; UT=1; DO=1; RA=1; KIND="UNATTENDED normal-path (no slpa) DCP-off run" ;;   # S5 + appledrm.test_sleep_off: the DCP firmware shut down for the suspend, never restarted; reboot after
    S5) DS=32; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; WO=1; UT=1; KIND="UNATTENDED normal-path (no slpa) USB-teardown run" ;;   # S4 + dwc3_apple.test_deep_teardown: live USB-C cores stopped before the suspend, restarted after
    S4) DS=32; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; WO=1; KIND="UNATTENDED normal-path (no slpa) wakeup-off run" ;;   # S3 with the USB-C ports' wakeup disabled
    T0) DS=32; PMP=0; CTL=1; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; KIND="UNATTENDED normal-path (no slpa) timer control run" ;;   # the S2R timer alone on the normal path: does it reset without slpa?
    Y1T) DS=32; PMP=0; CTL=65; [ $HM = 0 ] && HM=0xe00; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; RA=1; KIND="UNATTENDED normal-path (no slpa) domain-off probe run" ;;   # Y1 + the S2R timer written after the domain step, as a probe of how far Aura got
    Y1) DS=32; PMP=0; CTL=64; HM=0xe00; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; RA=1; KIND="UNATTENDED normal-path (no slpa) domain-off bisect run" ;;   # Y with only atc0/1/2_usb
    Y2) DS=32; PMP=0; CTL=64; HM=0x03f; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; RA=1; KIND="UNATTENDED normal-path (no slpa) domain-off bisect run" ;;   # Y with only the external displays' chains
    Y3) DS=32; PMP=0; CTL=64; HM=0x1c0; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; RA=1; KIND="UNATTENDED normal-path (no slpa) domain-off bisect run" ;;   # Y with only the panel DCP's chain
    Y) DS=32; PMP=0; CTL=64; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; RA=1; KIND="UNATTENDED normal-path (no slpa) domain-off check run" ;;   # image 56's held domains off and back, no slpa, no timer
    G56) DS=32; PMP=0; CTL=128; AOP=3; KIND="UNATTENDED normal-path (no slpa) image check run" ;;   # image 56 on the normal path, marker only
    X) DS=62; PMP=1; CTL=127; AOP=3; PIDS=${PIDS:-0x1000} ;;   # R + image 56's held domains off before quiesceHW (aura-ctl 64)
    S3) DS=32; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; KIND="UNATTENDED normal-path (no slpa) domain-reason run" ;;   # S2 with the per-domain 'held' lines
    U2) DS=32; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; UB=1; KIND="UNATTENDED normal-path (no slpa) unbind run" ;;   # U again; run.sh now skips a dwc3 whose core never probed (U oopsed there)
    S8) DS=32; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; WO=1; UT=1; DO=1; RA=1; SK=${SK:-afr}; KIND="UNATTENDED normal-path (no slpa) afr-kept run" ;;   # S6 + pmgr_pwrstate.test_sleep_keep=afr: does gfx power up after the wake when its parent afr stayed on?
    S7) DS=32; PMP=0; CTL=0; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; PC=0x300; KIND="UNATTENDED normal-path (no slpa) PCPM check run" ;;   # S3 + pmp_report.test_pcpm 0x300: PCPM0/1 asserted at PM_SUSPEND_PREPARE, withdrawn at PM_POST_SUSPEND (no PMP sleep on this path)
    R7) DS=62; PMP=1; CTL=63; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; WO=1; UT=1; DO=1; RA=1; PC=0x300; SK=${SK:-afr} ;;   # R6 + PCPM0/1 asserted for the suspend, withdrawn after the PMP's IDLE (macOS trace step 6); a new step: attended first
    R6) DS=62; PMP=1; CTL=63; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; WO=1; UT=1; DO=1; RA=1; KIND="UNATTENDED slpa run (a variation of R)" ;;   # R + S6's Linux-side domain-offs (USB-C teardown, DCP firmware off): 83 of 200 domains on
    V) DS=62; PMP=1; CTL=63; AOP=3; PIDS=${PIDS:-0x1000}; GD=1; UB=1 ;;   # R + the same unbinds
    *) echo "run A to N, P, Q, R, S, S2, U, V, W, G55"; exit 2 ;;
esac
findmnt /boot >/dev/null || { echo "/boot is not mounted"; exit 1; }
[ "$(sha256sum /boot/m1n1/boot.bin | cut -c1-16)" = 76f850895fed53d1 ] || { echo "ESP boot.bin is not the default"; exit 1; }
echo "run $RUN: deep_steps=$DS pmp-sleep=$PMP aura-ctl=$CTL pmp-release=$REL aop=$AOP wake-extra=${WX:-none} pmp-release-ids=${PIDS:-none}, 1 deep cycle, $ALARM s alarm, counters on; next: ${NEXT:-none}"
[ "$DRY" = --dry ] && exit 0
echo $DS | sudo tee $L/deep-steps >/dev/null
echo 1 | sudo tee $L/suspend-cycles >/dev/null
echo $ALARM | sudo tee $L/suspend-alarm >/dev/null
echo deep | sudo tee $L/sleep-modes >/dev/null
sudo touch $L/pmgr-counters $L/force-ro
if [ $PMP = 1 ]; then sudo touch $L/pmp-sleep; else sudo rm -f $L/pmp-sleep; fi
if [ $CTL != 0 ]; then echo $CTL | sudo tee $L/aura-ctl >/dev/null; else sudo rm -f $L/aura-ctl; fi
# aop.sleep_ap_idle (worklog 2026-11-05 23:55): 0 none (runs A to I), 3 the AOP queue stop and 0x201 before slpa
echo $AOP | sudo tee $L/aop-sleep-mode >/dev/null
if [ -n "$WX" ]; then echo "$WX" | sudo tee $L/wake-extra >/dev/null; else sudo rm -f $L/wake-extra; fi
if [ -n "$PIDS" ]; then echo "$PIDS" | sudo tee $L/pmp-release-ids >/dev/null; else sudo rm -f $L/pmp-release-ids; fi
if [ $GD = 1 ]; then sudo touch $L/genpd-dump; else sudo rm -f $L/genpd-dump; fi
if [ $HM != 0 ]; then echo $HM | sudo tee $L/aura-held-mask >/dev/null; else sudo rm -f $L/aura-held-mask; fi
if [ -n "$SK" ]; then echo "$SK" | sudo tee $L/sleep-keep >/dev/null; else sudo rm -f $L/sleep-keep; fi
if [ $PC != 0 ]; then echo $PC | sudo tee $L/pcpm >/dev/null; else sudo rm -f $L/pcpm; fi
if [ $DO = 1 ]; then echo 1 | sudo tee $L/dcp-off >/dev/null; else sudo rm -f $L/dcp-off; fi
if [ $UT = 1 ]; then echo 1 | sudo tee $L/usb-teardown >/dev/null; else sudo rm -f $L/usb-teardown; fi
if [ $WO = 1 ]; then printf '%s\n' 702280000.usb b02280000.usb f02280000.usb | sudo tee $L/wakeup-off >/dev/null; else sudo rm -f $L/wakeup-off; fi
if [ $RA = 1 ]; then sudo touch $L/reboot-after; else sudo rm -f $L/reboot-after; fi
if [ $UB = 1 ]; then printf '%s\n' "apple-drm soc:display-subsystem" "apple-dcp 389c00000.dcp" "apple-dcp 289c00000.dcp" "apple-dcp 315c00000.dcp" "dwc3-apple 702280000.usb" "dwc3-apple b02280000.usb" "dwc3-apple f02280000.usb" | sudo tee $L/unbind-before >/dev/null; else sudo rm -f $L/unbind-before; fi
if [ $REL = 1 ]; then echo deep | sudo tee $L/pmp-release-modes >/dev/null; else sudo rm -f $L/pmp-release-modes; fi
sudo rm -f $L/discharge $L/poke-wakemask
sudo bash $H/install.sh suspendall | tail -1
if [ $RUN = W ] || [ $RUN = P ] || [ $RUN = Q ] || [ $RUN = G55 ] || [ $RUN = S ] || [ $RUN = S2 ] || [ $RUN = U ] || [ $RUN = U2 ] || [ $RUN = S3 ] || [ $RUN = G56 ] || [ $RUN = Y ] || [ $RUN = Y1 ] || [ $RUN = Y1T ] || [ $RUN = T0 ] || [ $RUN = S4 ] || [ $RUN = S5 ] || [ $RUN = S6 ] || [ $RUN = S7 ] || [ $RUN = S8 ] || [ $RUN = Y2 ] || [ $RUN = Y3 ]; then
agent-notify send --title "S2R wake-bisect run: starting" --tags "robot" --message \
"Unattended, no slpa (run $RUN, wake_extra=${WX:-none}, pmp-release-ids=${PIDS:-none}): the Mac reboots in ~30 s, suspends ~2 min later and either wakes on the $ALARM s alarm or resets itself on the watchdog. Nothing to do." | tail -1
else
agent-notify send --title "S2R run $RUN: starting now" --priority high --tags "robot,warning" --message \
"Mac reboots in ~30 s; screen stays dark. ~2 min: it suspends with slpa; $ALARM s later the alarm. Don't touch keys, trackpad or lid.$( [ $KEY = 1 ] && echo "
THIS RUN: press the power key ONCE, briefly, 3 min after this push (not before 2:50, not after 3:40); tell me the time you pressed it." )
1) Works or resumes: result in the chat within ~6 min.
2) Disk dead: a high-priority 'Mac dead-man switch' push; the Mac resets itself. Nothing to do.
3) No chat message and no push within 10 min: hold power ~10 s until off, wait 5 s, press once. Then tell me 'reset by hand' and when." | tail -1
fi
P=$(mktemp)
cat > $P <<E
First remove ~/.local/state/deepidle/resume. This boot is $KIND $RUN (worklog 2026-11-05 10:02; D to F: the evening entry on image 52; G, H: image 53): image 53, deep_steps=$DS, pmp-sleep=$PMP, aura-ctl=$CTL (1 PMGR S2R timer, 2 every core into macOS's deep sleep, 4 quiesceHW's domains, 8 its ClkGen/PLL-off; psci_dbg[19..22] the AFR, SIO, SIO_CPU and PLL-off registers before<<32|after, [23] poll timeouts; run.sh logs 'aura ctl', psci_dbg[17] 0x53000000xx = the word Aura read, [18] 1 = timer written), 1 deep cycle, $ALARM s alarm, PMGR counters on, root ro, dead-man switch. FIRST read the ntfy "Mac dead-man switch" pushes (worklog 2026-11-05 15:57: they hold the resume, the counters, aura dbg and SART lines; never print the topic). Then work out what happened from uptime vs resume.log, the Pi watcher kmsg and the newest results-psci-efi-suspendall-*/run.log: a resume (read 'pmgr counters after deep 1': SLP_S2R / SYS_S2R_AOP above 0 = the SoC went down; psci_dbg[13] 3 = it came back through RVBAR with no wake line; apple-sart lines; nvme errors; the dead-man regs), or a reset (time from echo mem to the next kernel start: about 144 s = WD1 at 120 s, i.e. with aura-ctl 2 or 3 the cores powered down but the SoC never restarted them, as images 32 to 36; about 204 s = Linux resumed through RVBAR then hung; 94 s cold boot; 124 s SMC timeout; ask the owner if they reset by hand). Read-only btrfs scrub if any btrfs error appeared. Then remove deep-steps, pmp-sleep, aura-ctl, pmp-release-modes, pmgr-counters, force-ro, aop-sleep-mode, wake-extra, pmp-release-ids, genpd-dump, unbind-before, reboot-after, aura-held-mask, wakeup-off, usb-teardown, dcp-off, pcpm, sleep-keep; check boot.bin 76f850895fed53d1 and next_entry unset. Record in the worklog, s2r-status.json, status.md and the board; push GH-8 and main; tell the owner the result right away.$( [ $RUN = D2 ] && echo " D2 reading (worklog entry 'run D'): next kernel about 86 s after echo mem = the S2R timer's own reset, independent of the alarm; about the alarm + 56 s (about 146 s) = the SoC slept and the alarm cold-booted it; a dead-man push = Linux resumed with the SoC up." )$( [ $RUN = E ] && echo " E reading (worklog entry 'run D2'): the S2R timer alone resets about 85 s after echo mem (D, D2). E adds every core into macOS's deep sleep: about 85 s again = the timer needs quiesceHW's clock/PLL steps too; about 144 s = WD1, the cores went down but the SoC never took over; a resume (pmgr counters SLP_S2R > 0, psci_dbg[13] 3) or a reset timed by the 30 s alarm = the SoC got further." )$( [ $RUN = F ] && echo " F reading (worklog entry 'run E'): D, D2 and E all reset about 85 s after echo mem (the S2R timer). F has the cores without the timer: about 144 s (WD1) = the cores really power down and nothing restarts them; a dead-man push or a resume on the 30 s alarm = bit 2 does not really power the cores down, so E did not test what it meant to." )$( [ $RUN = A ] && echo " A reading (worklog entries 'IO RVBAR', 17:36 and 17:41): the test kernel restores the ANS wrapper's IO RVBAR (0x347050000). In run.log or the dead-man push: 'TEST iorvbar: kept 0x10000004001' = slpa does not clear it (the lead is wrong; the ANS fails for another reason); 'was 0x..., restored 0x10000004001' then the disk answers = the fix works; restored but 'ANS did not boot' again = the IO RVBAR is one of several things slpa resets (read the dead-man IORVBAR word and ANS cpu status)." )$( [ $RUN = C ] && echo " C reading (worklog entry 'the PMP crash in run C was a double SetAPPower'): the test kernel now sends the PMP's IDLE once (run C on 16:01 crashed the PMP by sending SetAPPower 0x201 twice: the firmware panics 'Invalid AP power'). 'PMP SetAPPower/SetIOPPower IDLE: 0' = the PMP accepted macOS's step 5; then read the PMGR counters (SLP_S2R > 0 = the SoC went further) and whether the PMP answers after the wake (on 10-23 its wake from IDLE failed without a power cycle). A PMP crash again = read its crashlog lines in the dead-man push or run.log." )$( case $RUN in J|K) echo " $RUN reading (J adds aura-ctl 16, image 54: the five soc-clusters' targets to 0 before the clocks; psci_dbg[6..10] before<<32|after, unattended 11-06 00:18 gave PACC0/1 0x10, ANE0/AVEMSR 0x00, DISPLAY 0x10 with its bit-4 poll timing out)." ;; esac )$( case $RUN in J|K) echo " J/K reading (worklog 2026-11-05 23:21 to 2026-11-06 00:01, the AOP's sleep handshake): run I reset about 85 s after echo mem. J adds what macOS tells the AOP before slpa: dmesg 'TEST queues stopped for system sleep: 12 of 12' and 'TEST SetAPPower 0x201 for system sleep: 0' before 'MBSE = slpa'. PMGR counters SYS_S2R_AOP or SLP_S2R above 0 = the SoC went further; about 85 s again = the AOP was not what the entry waited for either. An AOP crash line = read its PC (0x1002880 was the ring writer)." ;; esac )$( [ $RUN = L ] && echo " L reading (worklog 2026-11-06 'run J' and 'macOS's own wake mask' entries; since 16:10 the mask step works, ioremap_np): J reset 86 s after echo mem with the AOP's queues stopped (12 of 12) and its 0x201 acked. Runs D to J all ran with Linux's wake mask (all 0, every PMGR wake source enabled); L writes macOS's mask (only its 22 sources) in suspend_late before slpa ('sleep: wake mask ... -> ...'). About 85 s again = a pending wake source was not what held the entry; about 145 s = WD1 (the mask blocked Aura's heartbeat, worklog 11-05 08:00, and the entry still did not complete); a dead-man push or a resume = read 'sleep: wake status' (which source woke it) and the PMGR counters (SLP_S2R / SYS_S2R_AOP > 0 = the SoC slept). If nothing comes back and the owner had to press the power key or reset by hand, ask them which and when: a real S2R that the alarm cannot wake through macOS's mask is possible." )$( [ $RUN = M ] && echo " M reading (worklog 2026-11-06 'run L'): L (macOS's wake mask) reset at about 146 s = WD1, not the 85 s timer. M is L with the owner pressing the power key once about 3 min after the push (about 50 s after echo mem). A resume = the key woke it: read the PMGR counters (SLP_S2R / SYS_S2R_AOP > 0 = the SoC really slept), psci_dbg[13] (3 = RVBAR path), 'sleep: wake status'; then expect the ANS dead and the dead-man reset. About 146 s again = the key does not wake it through macOS's mask either. Ask the owner when they pressed the key." )$( [ $RUN = W ] && echo " W reading (worklog 2026-11-06 'wake bisection'): no slpa, no S2R timer, aura-ctl 0; macOS's wake mask with wake_extra=$WX also enabled (the module now writes it at PM_SUSPEND_PREPARE: 'sleep: wake mask read ...' and 'sleep: wake mask now ...' reach the Pi kmsg before 'PM: suspend entry'; on wake 'sleep: wake status ...; wake mask restored'). A resume on the 30 s alarm = 'wake' (read 'sleep: wake status'); a reset about 145 s after echo mem (WD1) = 'nowake'. In the test kernel /boot may be unmounted: sudo mount /boot before arming (findmnt /boot). Record it with python3 tools/wake-bisect.py result wake|nowake (state in data/wake-bisect/state.json), commit, then arm the next unattended: WX=\$(python3 tools/wake-bisect.py next) bash harness/psci-efi/attended.sh W, until one bit is left; check that bit alone too. Then run L with that bit added (WX of the bit, run L with WX: set WX for L too), unattended per the owner's 15:15 rule. Stop and tell the owner after any hand reset, btrfs error or missing default boot.bin." )$( [ $RUN = P ] && echo " P reading (worklog 2026-11-06 'ISP_SYS release' entry): normal path, no slpa; pmp_report.test_release_ids=$PIDS also withdraws ISP_SYS (entry 12) in suspend_noirq. Expect dmesg 'TEST request 12 withdrawn for sleep: 0, ack 0x...' (with the display ones the ack word should reach 0) and 'asserted' after the wake, 'pmp requests after resume' back at 0xf000, a resume on the alarm with all CPUs, no new device errors (the SMC endpoint 0x20 line is old). If that holds, arm N unattended (L + this release; owner's 15:15 rule): bash harness/psci-efi/attended.sh N. A failure to re-assert (dev_err 'not asserted after sleep') or a hang = stop and record." )$( [ $RUN = Q ] && echo " Q reading (worklog 2026-11-06 'PMP requests before slpa' entry): normal path, no slpa, no PMP IDLE; deep_steps 32 withdraws the display requests and ISP_SYS in macsmc-reboot's suspend_late ('sleep: PMP requests released before slpa (0)', TEST request lines with the ack word reaching 0x0) and asserts them in resume_early ('asserted again'); 'pmp requests after resume' back at 0xf000; a resume on the alarm with all CPUs; no 'not asserted' error. If that holds, arm N unattended (bash harness/psci-efi/attended.sh N; owner's 15:15 rule)." )$( [ $RUN = G55 ] && echo " G55 reading (worklog 2026-11-06 'image 55' entry): image 55 (boot.bin.psci-test55, e53a793bb3c942c7) on the normal path, aura-ctl 0x80 (marker only; psci_dbg[17] 0x5300000080): a resume on the alarm with online 0-9 = the image is sound; then arm R unattended (bash harness/psci-efi/attended.sh R)." )$( [ $RUN = S8 ] && echo " S8 reading (worklog 2026-11-06 'S8 armed' entry): S6 (USB-C wakeup off and teardown, DCP firmware shut down, reboot-after) plus pmgr_pwrstate.test_sleep_keep=afr (run.log 'sleep keep' line; dmesg 'TEST: afr kept on through system sleep'). S6 resumed with 'PS gfx: Failed to reach power state 0xf' because, the question is, afr (gfx's parent) had gone off. Expected: afr in the genpd on-list at syscore suspend (84 of 200), and after the wake no 'PS gfx' error and the GPU working (dmesg asahi lines after the resume; no GPU errors). If 'PS gfx' still fails: afr is not the cause; next suspect the PMP's GFX request (0x400). The run reboots itself 20 s after a 'back' line: read it from the previous boot's journal.")$( [ $RUN = S7 ] && echo " S7 reading (worklog 2026-11-06 'S7 armed' entry): S3 (normal path, the PMP release, genpd dump) plus pmp_report.test_pcpm 0x300 (run.log 'pcpm' line): dmesg 'pmp-report: TEST pcpm 0x300 asserted: 0, request ... ack ...' at PM_SUSPEND_PREPARE (ack must have 0x300 set) and 'TEST pcpm 0x300 withdrawn: 0' at PM_POST_SUSPEND. Expected: back on the alarm, both acked, nothing else changed (compare S3 and S5: 32 to 33 s, online 0-9, PMP requests back to 0xf000). An assert error (-110) = the PMP does not take CPU-complex requests from the AP; then R7 is moot. A WD1 = asserting them changed something on the way down.")$( [ $RUN = R7 ] && echo " R7 reading (worklog 2026-11-06 'S7 armed' entry): R6 plus PCPM0/1 asserted at PM_SUSPEND_PREPARE and withdrawn in macsmc's suspend_late right after the PMP's SetAPPower/SetIOPPower IDLE, i.e. after slpa, as macOS's trace step 6 ('sleep: TEST pcpm release' only on an error; the pmp-report 'withdrawn' line). R6 ended in the S2R timer's reset at 86 s. 86 s again = the PCPM transition is not it either. Anything else is new (see R6's reading).")$( [ $RUN = R6 ] && echo " R6 reading (worklog 2026-11-06 'R6 armed' entry): run R (every macOS sleep step, aura-ctl 63 incl. the S2R timer; R ended in the timer's reset at 86 s) with S6's Linux-side domain-offs: USB-C wakeup off, the dwc3 teardown, the DCP firmware shut down (run.log 'wakeup off', 'usb teardown', 'dcp off'; S6 had 83 of 200 domains on at syscore suspend, only sio and the apcie_gp pair held, data/s2r-domains/2026-11-06-2119-s6-dcp-off-held.txt). The question: does the PMGR's S2R entry complete now? About 86 s from echo mem to the next kernel = the timer's reset as in R: the devices were not what it waited for. Anything else is new: a resume with SLP_S2R / SYS_S2R_AOP counters above 0 (the SoC went down) or psci_dbg[13] 3 (back through RVBAR); about 145 s = WD1 (something stalled earlier than in R; compare S6). reboot-after reboots a run that came back (displays dead). The genpd and TEST lines are in the previous boot's journal (journalctl -k -b -1) if it came back, else only the Pi kmsg. Save what there is to data/s2r-domains/ (dated).")$( [ $RUN = R ] && echo " R reading: N (L + the PMP's requests at 0 before slpa) with aura-ctl 63: image 55 writes each parked secondary's PMGR stop request (CPUSTART + 0, macOS's trace step 6) before releasing it into cpu_sleep(true). psci_dbg[17] 0x530000003f. About 86 s = the timer's reset again; a resume or dead-man push = read the PMGR counters (SLP_S2R, SYS_S2R_AOP > 0 = the SoC slept); about 145 s = WD1." )$( [ $RUN = S ] && echo " S reading (worklog 2026-11-06 'run R' entry): normal path, no slpa; deep_steps 96 = the PMP's requests released (32) + 'sleep: ps suspend_late: name=state ...' and '... N of M domains not off' (64), again at resume_early. State 0xf = on, 4 = clock-gated. Save the lines to data/s2r-domains/ (a dated file), compare with the ADT's always-on domains and with what macOS powers off, and record which domains Linux leaves on at slpa's place. A hang or reset = the dump's register reads are unsafe at that point: record, do not repeat." )$( [ $RUN = S2 ] && echo " S2 reading (worklog 2026-11-06 'run S' entry): normal path, no slpa; the PMP release (deep_steps 32) and pm_genpd.test_dump: at syscore suspend (after every noirq phase, just before PSCI SYSTEM_SUSPEND) the kernel logs 'genpd test syscore suspend: name name* ...' ('*' = always-on) and 'N of M domains on'. Expect a resume on the alarm as run Q. Save those lines to data/s2r-domains/ (a dated file), and compare: always-on ones (the DT's apple,always-on) vs ones held by a device that stays active, against what macOS has off at sleep (everything but the AON domains, the AOP, the SMC, the PMP and the memory)." )$( [ $RUN = U ] && echo " U reading (worklog 2026-11-06 'run S2' entry): S2 with the display stack (apple-drm, the three apple-dcp) and the three USB-C dwc3s unbound before the suspend ('unbind <drv> <dev>: 0' lines in run.log). Compare 'genpd test syscore suspend' with data/s2r-domains/2026-11-06-1655-syscore-suspend.txt: the disp*/dispext*/pmp-disp*/atc*_usb domains should be off. A resume on the alarm with no new errors = arm V unattended (R + the unbinds: bash harness/psci-efi/attended.sh V). A hang = the unbinds are unsafe; record and drop the one at fault." )$( [ $RUN = S6 ] && echo " S6 reading (worklog 2026-11-06 'S6 armed' entry): S5 (USB-C wakeup off, USB teardown) plus appledrm.test_sleep_off=1 (run.log 'dcp off' line): each DCP's suspend shuts its RTKit firmware down and clears CPU_CONTROL instead of setting the wake path (dmesg 'TEST: firmware shut down for deep suspend' x3, or 'firmware shutdown for deep suspend failed'). Expected: the 13 display domains (pmp-disp*, disp*/dispext*_cpu0/fe/sys, afr) leave the 'genpd test syscore suspend held' lines (S5: data/s2r-domains/2026-11-06-1817-s5-usb-teardown-held.txt, 96 of 200); a resume on the alarm with dead displays; reboot-after then sysrq-reboots about 20 s after the run (expected, no hand reset). A WD1 (about 145 s) = genpd powering a display domain off stalls the SoC like Aura did (Y2T), even with the firmware stopped. Read the run from the saved results dir and the journal of the previous boot (journalctl -b -1). Modules before this change: /var/lib/deepidle/mods-pre-dcpoff. Save the held lines to data/s2r-domains/ (dated).")$( [ $RUN = S5 ] && echo " S5 reading (worklog 2026-11-06 'S5 armed' entry): S4 (wakeup off on the three dwc3 USB-C devices) plus dwc3_apple.test_deep_teardown=1 (run.log 'usb teardown' line): at PM_SUSPEND_PREPARE dwc3-apple stops a live core (dmesg 'TEST: core stopped for deep suspend (role R): 0', R 1 host, 2 device) and at PM_POST_SUSPEND starts it again ('TEST: core restarted after deep suspend (role R): 0'); phy-apple-atc.test_restore_pd_off (default on in this test kernel) restores the PHY after its domain was off (dmesg 'Failed to restore mode' / 'did not power down' = trouble). Expected: back on the alarm, and atc0_usb and atc2_usb drop out of the 'genpd test syscore suspend held' lines (S4: data/s2r-domains/2026-11-06-1808-s4-wakeup-off-held.txt, 98 of 200 on). After the wake: the Logitech receiver on f02280000 re-enumerated (dmesg 'Logitech USB Receiver' after the resume, lsusb), 702280000 back in gadget mode (/sys/class/udc/702280000.usb), USB errors noted. A WD1 or hang = the teardown or the restart is at fault (modules saved in /var/lib/deepidle/mods-pre-usbteardown with the old initramfs). Save the held lines to data/s2r-domains/ (dated).")$( [ $RUN = S4 ] && echo " S4 reading (worklog 2026-11-06 'run Y2T' entry): Aura cannot force the held domains off (Y1T, Y2T stalled before the timer), so Linux must let them go. S4 = S3 (normal path, PMP release, genpd reason dump, no Aura steps) with wakeup disabled on the three dwc3 USB-C devices and their xHCI ('wakeup off: ...' lines in run.log). Compare the 'genpd test syscore suspend held' lines with data/s2r-domains/2026-11-06-1718-s3-held-reasons.txt: atcN_usb for a port with no core up should now be off; a port with its core up stays held (syscore). Expect a resume on the alarm with all CPUs; note USB errors after the wake. Save the lines to data/s2r-domains/ (dated)." )$( [ $RUN = T0 ] && echo " T0 reading (worklog 2026-11-06 'run Y1T' entry): the control for Y1T. Normal path, no slpa, no domain step; aura-ctl 1 = only the PMGR S2R timer, written just before Aura's wait. Next kernel about 60 to 90 s after echo mem = the timer resets the SoC without slpa too, so Y1T's 145 s means Aura stalled at the USB-C domain-off writes or polls (before the timer write): then look at the writes themselves (statically: atcN_usb register bits, the poll, the parent atcN_usb_aon; and Y2/Y3 with the probe for the display groups). A resume on the alarm (back, rc=0) and no reset by 120 s = the timer needs slpa to count: Y1T says nothing, and only X (slpa path) can tell the writes apart. 145 s = the timer alone hangs the normal path (new)." )$( [ $RUN = Y1T ] && echo " Y1T reading (worklog 2026-11-06 'run Y1' entry): Y and Y1 (USB-C only) both ended in WD1 (about 145 s), which cannot tell Aura stalling at the domain-off writes from Linux hanging in its resume. Y1T is Y1 (mask $HM) plus the PMGR S2R timer (aura-ctl 65), which Aura writes after the domain step; on the slpa runs the timer reset the SoC about 86 s after echo mem even after Linux had resumed (D, D2). So: next kernel about 60 to 90 s after echo mem = Aura got past the writes (the hang is in Linux's resume against the power-cycled devices); about 145 s = Aura stalled at the writes or polls (or the timer does not fire without slpa: then compare with a timer-only normal-path run before concluding). A resume that survives past 90 s would be new: read everything." )$( case $RUN in Y1|Y2|Y3) echo " $RUN reading (worklog 2026-11-06 'run Y' entry): Y (all 12 held domains off on the normal path) ended in WD1 (about 145 s, no dead-man push). Image 57 (boot.bin.psci-test57, ae5f5e93323269a6; psci_dbg at offset 0x137470) turns off only the mask $HM (bits 0-2 dispext0 cpu0/fe/sys, 3-5 dispext1, 6-8 disp0, 9-11 atc0/1/2_usb); run.log 'aura ctl ... mask'. Y1 = USB-C only, Y2 = the external displays (nothing attached), Y3 = the panel's DCP. A resume on the alarm = that group is not the hang (read 'aura dbg (words ...)' word 23 high half = poll timeouts, the device errors after the wake; the run sysrq-reboots itself 20 s after it ends); about 145 s = it is (or Linux's resume hangs with it). Then the next group: Y1, then Y2, then Y3, each unattended; record each. After all three, decide X's mask: the groups that came back are safe for X." ;; esac )$( [ $RUN = Y ] && echo " Y reading (worklog 2026-11-06 'run Y' entry): normal path, no slpa, no S2R timer, no cores off; aura-ctl 64 only: Aura writes the 12 held PMGR domains (three display chains, atc0/1/2_usb) off before its WFI wait and restores them on wake (parents first). The DCPs and USB-C controllers lose their state, so expect display/USB errors after the wake; the run reboots itself 20 s after it ends (reboot-after). Read run.log 'aura dbg (words ...)' at the new offset: word 23 high half (bits 32-43) = poll timeouts per domain (0 = every domain reached off), word 17 0x5300000040. A resume on the alarm with 0 timeouts = the domain-off writes are safe: tell the owner X is de-risked. A WD1 reset (~145 s) or a hang = the writes or polls stall the fabric: record, and X would need the offending domain dropped. Also read 'genpd test syscore suspend' (as S3) and the device errors after the wake." )$( [ $RUN = G56 ] && echo " G56 reading (worklog 2026-11-06 'image 56' entry): image 56 (boot.bin.psci-test56, 20f6d711f9f7add5) on the normal path, aura-ctl 0x80 (marker only; psci_dbg[17] 0x5300000080, read at the new offset 0x137430): a resume on the alarm with online 0-9 = the image is sound; then run X (R + the held domains off) needs ONE ATTENDED run first: tell the owner and wait for them to be at the Mac before arming it (bash harness/psci-efi/attended.sh X)." )$( [ $RUN = X ] && echo " X reading (worklog 2026-11-06 'image 56' entry): R (every macOS trace step) plus image 56's step: Aura writes the 12 PMGR domains Linux keeps on (the three display chains cpu0/fe/sys, atc0/1/2_usb) to off, children first, before quiesceHW's domains (afr) and the S2R timer. About 86 s = the timer's reset again: those domains are not what the entry waits for; about 145 s = WD1 (a domain-off write or poll hung the fabric, or the cores went down and nothing restarted them); a resume or dead-man push = read the PMGR counters (SLP_S2R, SYS_S2R_AOP > 0 = the SoC slept) and psci_dbg[23] bits 32-43 (poll timeouts per domain)." )$( [ $RUN = S3 ] && echo " S3 reading (worklog 2026-11-06 'run U2' entry): S2 again (normal path, the PMP release, pm_genpd.test_dump, no unbinds) on a test kernel whose dump also prints, after 'N of M domains on', one 'genpd test syscore suspend held NAME: susp S/D [defer] [awake]; dev X(syscore|wakepath|not-noirq) ... child C ... nodev FWNODE ... unbound DEV' line per non-always-on domain still on. Expect a resume on the alarm as S2. Save the lines to data/s2r-domains/ (dated file) and sort the held domains by reason: a device not counted (syscore, awake path, missed noirq), a child on, or DEFER_OFF with a consumer lacking a driver. Then decide per domain how Linux can let it go off at sleep as macOS does (e.g. no DEFER_OFF once boot is over, wakeup off for that device), static work first." )$( [ $RUN = U2 ] && echo " U2 reading (worklog 2026-11-06 'run U' entry): U oopsed in dwc3_apple_remove on b02280000 (its core never probed: NULL drvdata) before any suspend. U2 is U with run.sh skipping a dwc3 port without an xhci-hcd child ('unbind dwc3-apple ...: skipped, core not probed'). Compare 'genpd test syscore suspend' with data/s2r-domains/2026-11-06-1655-syscore-suspend.txt: the disp*/dispext*/pmp-disp* domains and the unbound ports' atc*_usb should be off; also note whether the skipped ports' atc*_usb stay on. The run reboots itself 20 s after it finishes. A resume on the alarm with no new errors = arm V unattended (bash harness/psci-efi/attended.sh V; it uses the same skip). A hang or oops = record and drop the unbind at fault." )$( [ $RUN = V ] && echo " V reading: R (every macOS trace step) with the display stack and the USB-C dwc3s unbound first, so their domains are off as in macOS. About 86 s = the timer's reset again (the domains left are always-on ones and PCIe/SIO/afr); a resume or dead-man push = read the PMGR counters (SLP_S2R, SYS_S2R_AOP > 0 = the SoC slept)." )$( [ $RUN = N ] && echo " N reading: L (every macOS step found so far + macOS's wake mask) with the PMP's display and ISP_SYS requests withdrawn just before slpa (deep_steps bit 32; in C, I, J and L the noirq release came after the PMP's IDLE and was refused), so the PMP's request word is 0 before slpa as in macOS's trace (0x8300 -> 0x300 -> 0x200 -> 0, then the cores sleep). About 86 s = the timer's reset again (then the next difference in the trace: macOS requests and then clears the CPU complexes PCPM0/PCPM1 through the PMP's target word, and writes PMGR 0x2902801c0); a resume or dead-man push = read the PMGR counters (SLP_S2R, SYS_S2R_AOP > 0 = the SoC slept)." )$( case $RUN in G|H|I) echo " $RUN reading (worklog entry 'image 53'): D, D2, E reset about 85 s after echo mem (the S2R timer resets when the entry does not complete); F 145 s (WD1). About 85 s again = these quiesceHW steps are not what the entry waits for either; a resume (pmgr counters SLP_S2R > 0, psci_dbg[13] 3), a reset timed by the 30 s alarm, or any other time = the SoC got further. Then G before H." ;; esac ) PMP display requests released for sleep: $REL (pmp-release-modes deep; dmesg TEST request lines).$( [ -n "$NEXT" ] && echo " CHAIN: the owner is at the Mac for a series of attended runs (said on 2026-11-05 ~20:35: ready for attended tests. send notifications before starting each.). After recording this result and telling the owner (agent-notify), and only if this run left the Mac recovered (default boot, disk clean), arm the next: NEXT=\"$(echo $NEXT | cut -s -d" " -f2-)\" bash harness/psci-efi/attended.sh $(echo $NEXT | cut -d" " -f1) (it notifies the owner before it starts). If anything looks unsafe (a btrfs error, a hand reset, the default boot.bin missing), stop the chain and tell the owner." )${EXTRA:+ $EXTRA}
